package com.aoo.bcg.poker;import java.util.*;import java.util.stream.*;/**六合争牌：单、对、连对、三带二、飞机、顺子、炸弹及炸弹带三。*/final class LhzpRules{enum Type{PASS,SINGLE,PAIR,LINKED_PAIRS,TRIPLE_WITH_TWO,AIRPLANE,STRAIGHT,BOMB,BOMB_WITH_THREE}record Play(Type type,List<Integer>cards,int value,int chainLength){Play{cards=List.copyOf(cards);}}static List<Integer>deck(boolean ignored){return PokerCardCodec.deck(52);}static int rank(int c){return PokerCardCodec.rank(c);}static int point510k(int c){return 0;}static Play classify(Type d,Collection<Integer>in){List<Integer>c=List.copyOf(in);Map<Integer,Long>m=c.stream().collect(Collectors.groupingBy(LhzpRules::rank,TreeMap::new,Collectors.counting()));int min=m.keySet().stream().mapToInt(x->x).min().orElseThrow(),max=m.keySet().stream().mapToInt(x->x).max().orElseThrow();boolean cont=max-min+1==m.size();boolean ok=switch(d){case SINGLE->c.size()==1;case PAIR->c.size()==2&&m.size()==1;case LINKED_PAIRS->c.size()>=4&&c.size()%2==0&&cont&&m.values().stream().allMatch(n->n==2);case TRIPLE_WITH_TWO->c.size()==5&&m.containsValue(3L);case AIRPLANE->c.size()>=6&&m.values().stream().filter(n->n==3).count()>=2;case STRAIGHT->c.size()>=5&&cont&&m.values().stream().allMatch(n->n==1);case BOMB->c.size()>=4&&m.size()==1;case BOMB_WITH_THREE->c.size()>=7&&m.containsValue(4L);case PASS->false;};if(!ok)throw new IllegalArgumentException("invalid LHZP "+d);return new Play(d,c,max,m.size());}static boolean beats(Play n,Play p){if(p==null)return true;if(n.type()==Type.BOMB||n.type()==Type.BOMB_WITH_THREE)return p.type()!=n.type()||n.cards().size()<p.cards().size()||n.cards().size()==p.cards().size()&&n.value()>p.value();return n.type()==p.type()&&n.cards().size()==p.cards().size()&&n.value()>p.value();}static int prize(Play p,boolean fewerCardsWins,boolean x,boolean y){if(p.type()!=Type.BOMB&&p.type()!=Type.BOMB_WITH_THREE)return 0;int n=p.cards().size();return n<5?0:1<<Math.min(4,n-5);}}
